#!/bin/bash
# launchd wrapper for the escalations job (com.chalant.promptocracy-escalations.<slug>, one job per game, hourly at :17 from 08:00 to 23:00 in the
# game's time zone; the schedule is generated by schedule.mjs). Reads ONLY the keys the job needs from ~/chalantbot/.env (never prints them):
# the game's moderator token and the Messages API key. No Claude Code, no subscription token: the job makes a plain, tool-less API call.
set -u
export PATH="$HOME/.local/bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin"
ENV_FILE="$HOME/chalantbot/.env"
HERE="$(cd "$(dirname "$0")" && pwd)"
get() { grep -E "^$1=" "$ENV_FILE" 2>/dev/null | head -1 | cut -d= -f2- | sed -e 's/^["'"'"']//' -e 's/["'"'"']$//'; }
[ -f "$ENV_FILE" ] || { echo "escalations: no $ENV_FILE" >&2; exit 2; }
SLUG="${1:?usage: escalations-run.sh <game slug>}"
key="PROMPTOCRACY_MODERATOR_TOKEN_$(echo "$SLUG" | tr '[:lower:]-' '[:upper:]_')"
v="$(get "$key")"
[ -n "$v" ] || { echo "escalations: no $key in $ENV_FILE: $SLUG is not moderated from this machine" >&2; exit 2; }
export "$key=$v"
v="$(get PROMPTOCRACY_MODEL_API_KEY)"
[ -n "$v" ] || { echo "escalations: no PROMPTOCRACY_MODEL_API_KEY in $ENV_FILE" >&2; exit 2; }
export PROMPTOCRACY_MODEL_API_KEY="$v"
v="$(get PROMPTOCRACY_API)"; [ -n "$v" ] && export PROMPTOCRACY_API="$v"
exec /opt/homebrew/bin/node "$HERE/escalations.mjs" --slug "$SLUG"
